"use client";

import { useState, useEffect } from 'react';
import Container from 'react-bootstrap/Container';
import Nav from 'react-bootstrap/Nav';
import Navbar from 'react-bootstrap/Navbar';
import Button from 'react-bootstrap/Button';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { motion } from 'framer-motion';

import { FaCompass } from 'react-icons/fa';

function AppNavbar() {
  const pathname = usePathname();
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { href: "/", label: "Home" },
    { href: "/search", label: "Destinations" },
    { href: "/saved", label: "Saved" },
    { href: "/admin", label: "Admin" },
  ];

  return (
    <Navbar 
      expand="lg" 
      className={`navbar fixed-top transition-all duration-300 ${scrolled ? 'py-2 shadow-sm bg-white/90 backdrop-blur-md' : 'py-3 bg-transparent'}`}
      style={{
        transition: 'all 0.3s ease-in-out',
        backgroundColor: scrolled ? 'rgba(255, 255, 255, 0.95)' : 'rgba(255, 255, 255, 0.8)',
        backdropFilter: 'blur(10px)',
        boxShadow: scrolled ? '0 4px 30px rgba(0, 0, 0, 0.1)' : 'none'
      }}
    >
      <Container>
        <Navbar.Brand as={Link} href="/" className="fw-bold d-flex align-items-center" style={{ fontSize: '1.5rem' }}>
          <FaCompass className={`me-2 ${scrolled ? 'text-primary' : 'text-secondary'}`} size={28} />
          <span style={{ color: '#2c3e50' }}>Camiguin<span className="text-primary">Tourism</span></span>
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" className="border-0 shadow-none" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="ms-auto align-items-center gap-3">
            {navLinks.map((link) => {
              const isActive = pathname === link.href;
              return (
                <Link key={link.href} href={link.href} passHref legacyBehavior>
                  <Nav.Link className={`position-relative px-3 fw-semibold ${isActive ? 'text-primary' : 'text-dark'}`}>
                    {link.label}
                    {isActive && (
                      <motion.div
                        layoutId="navbar-underline"
                        className="position-absolute bottom-0 start-0 w-100 bg-primary"
                        style={{ height: '3px', borderRadius: '2px' }}
                        transition={{ type: "spring", stiffness: 350, damping: 30 }}
                      />
                    )}
                  </Nav.Link>
                </Link>
              );
            })}
            
            <motion.div whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}>
              <Link href="/search" passHref legacyBehavior>
                <Button variant="primary" size="sm" className="px-4 py-2 rounded-pill fw-bold shadow-sm d-none d-lg-block">
                  Book Now
                </Button>
              </Link>
            </motion.div>
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}

export default AppNavbar;
